@startuml

class SensorController {
  + username : string
  + password : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class TemperatureSensor extends Sensor {}

abstract class PowerSensor extends Sensor {}

class TemperatureSensor {
  + min : float
  + max : float
}

class PowerSensor {
  + counterReading : float
}

enum Unit {
  CELSIUS
  WATT
}

class Inhabitant {
  + username : string
  + password : string
  + isAdmin : boolean
}

class Room {
  + description : string
}

class Apartment {
  + address : string
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

SensorController "1" *-- "*" Sensor
SensorController "1" *-- "*" Inhabitant
SensorController "1" *-- "1" Apartment
Apartment "1" *-- "1..*" Room
Room "1" *-- "*" Sensor
Inhabitant "1" -- "*" Sensor : queries
Inhabitant "1" -- "*" Room : assignedTo
Sensor "1" *-- "*" MeasuredValue
Sensor "1" o-- "1" MeasuredValue : lastValue
EMonitor --> Sensor : checksThresholds
EMonitor --> SensorController : sendsAlerts

@enduml

